#!/usr/bin/env python3
"""Write the shared masthead into every page in this repo.

No build step runs on this site, so nine pages would otherwise each carry
their own hand-kept copy of the lockup and the nav — and drift. This script
holds the one copy. Each page marks where it goes:

    <!-- MASTHEAD:BEGIN (generated by scripts/apply-masthead.py) -->
    ...
    <!-- MASTHEAD:END -->

Edit the markup here, re-run the script, commit the pages it changed. The
first run replaces whatever <nav class="sitenav"> block a page still carries
and leaves the markers behind.

The nav order reads: the work first, then the loose pages, then the tools,
then the papers, then consulting last. aria-current marks the page the visitor
stands on.

Two changes on 2026-11-01, both the owner's call. The Shelf went: its carousel
moved into the Videos page, which already carried all 69 published videos, so
two tabs covered one thing. Academia arrived in its place, and the Treatise
tab now reads Non-Nominalism, the work's own name. The page moved to non-nominalism.html
the same day, so the URL now matches the name. Anything still pointing at
/treatise needs a redirect, which Cloudflare Pages handles through a _redirects
file this site does not yet carry.

Eleven links as of 2026-11-09, when Eleven Days arrived beside Techne as the
second tool. Ten of them wrapped to four centred rows at 400px — measured
2026-11-01, up from three because "Non-Nominalism" runs longer than "Treatise"
did. The row wraps rather than scrolling sideways or collapsing to a hamburger
— both ruled out deliberately: a hamburger hides the whole site behind
JavaScript, and a sideways scroll hides tabs with nothing to say it did.
Re-measure 375px after adding a twelfth.

This script also writes the calendar rail that sits at the foot of every
page — see THE CALENDAR RAIL further down.
"""

import math
import random
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PAGES = ROOT

BEGIN = "<!-- MASTHEAD:BEGIN (generated by scripts/apply-masthead.py) -->"
END = "<!-- MASTHEAD:END -->"

NAV = [
    ("videos.html", "Videos", False),
    ("exodus.html", "Project Exodus", False),
    ("non-nominalism.html", "Non-Nominalism", False),
    ("exit-interview.html", "Exit Interview", False),
    ("poetry.html", "Poetry", False),
    ("horrible-ideas.html", "Horrible Ideas", False),
    ("thoughts.html", "Thought of the Day", True),
    ("techne.html", "Techne", False),
    ("eleven-days.html", "Eleven Days", False),
    ("academia.html", "Academia", False),
    ("consulting.html", "Consulting", False),
]

# ─── THE CALENDAR RAIL ─────────────────────────────────────────────────────
# Site-wide chrome, so it gets written from here rather than pasted into
# thirteen pages: one strip fixed to the bottom edge of every page, filled by
# assets/eleven/band.js.
#
# It rides inside the MASTHEAD block although it paints at the foot of the
# page, because this is the one block every page already carries and
# position:fixed takes it out of flow anyway.
#
# TWO RAILS, deliberately unlike each other. The coloured one sits below the
# masthead carrying the plugin's own palette and a chain between its entries,
# and runs slow. The quiet one sits at the foot of the page in ivory and gold
# with the site's mascot between entries, and runs quicker. Matching their
# speeds would make the page read as one scrolling surface with the content in
# a hole in the middle.
#
# A four-line version of the upper rail, with a gloss drawer, came and went on
# 2026-11-09: at that height it pushed every page's own opening below the fold.
# Keep this one to a single line.
#
# site.css reserves the rail's height on <body>, including
# env(safe-area-inset-bottom). Change the rail's height there, not here, or
# the strip covers the last line of all thirteen pages.


def rail():
    out = [
        # the coloured rail, below the masthead: the plugin's own palette, a
        # motif behind each entry, a chain between them, running slow
        '<div class="eleven-band eleven-band--inflow" data-eleven-band',
        '     data-variant="chain" aria-label="Today in eleven calendars"></div>',
        # and the quiet one, fixed to the foot of the page, running quicker
        '<div class="eleven-band eleven-band--rail" data-eleven-band',
        '     aria-label="Today in eleven calendars"></div>',
        # engine first, then the script that reads it. Neither is deferred:
        # band.js waits for DOMContentLoaded itself, and /eleven-days needs
        # window.buildCalendars in place before its own page.js runs.
        '<script src="assets/eleven/engine.js"></script>',
        '<script src="assets/eleven/band.js"></script>',
    ]
    return "\n".join(out)

# ─── THE LOCKUP GLOBE ──────────────────────────────────────────────────────
# The ringed planet, drawn from our own vocabulary: a gold ring that wraps the
# equator, a warm ivory-to-shadow body, and the orange sun flare breaking at
# the upper left — the banner's chiaroscuro, in miniature. Inline SVG, so it
# stays sharp on near-black (Report A).
#
# REBUILT ON A PROJECTION (2026-11-01, the owner's call). Two faults, both
# geometric. The ring's arcs ran along y=50 while the body centred on cy=46,
# so the ring crossed 4px below the equator and only clipped the disc at its
# thinnest point; and the "rotation" was a scaleY pulse on those arcs, which
# reads as a breath rather than a turn — nothing ever went round the back.
#
# Both now come from one orthographic projection: a camera elevated TILT above
# the ring plane, a body of radius R, everything concentric on the group's
# origin. The equator projects to an ellipse of semi-axes R and R·sin TILT,
# and the ring bands are that same ellipse scaled out, so the ring bisects the
# sphere by construction. Depth sorting comes from paint order, in three
# layers: the ring's far half, then the body, then the ring's near half. The
# far half's apex sits inside the body's silhouette, so the body hides it and
# the ring visibly passes behind. The same sorting carries the ring's rotation:
# a bare ellipse turned in its own plane looks identical to itself, so globe.js
# rides density clumps round the bands and moves each one between the two ring
# groups as it crosses the limb.
#
# WHAT THIS FILE DRAWS, AND WHAT THE SCRIPT DRAWS. Everything here holds still
# because it does not depend on the body's longitude: the ring, the body, the
# shading, the latitude lines, the pole points. website/assets/globe.js adds
# the meridians, the polar hexagon, the surface spots and the ring's orbiting
# density clumps, and rewrites them per frame — see its header for the projection and the shared constants. A
# visitor with no JavaScript, or one who asked for reduced motion, therefore
# still gets a correctly tilted, correctly bisected ringed globe at rest.
#
# TILT and R repeat in globe.js. Change one, change both, re-run this script.

LF = chr(10)

TILT = math.radians(26)   # camera elevation above the ring plane
SIN_T = math.sin(TILT)
COS_T = math.cos(TILT)
R = 30.0                  # body radius, in the 200-unit viewBox
ROLL = -14                # the axis leans, the way a display globe does
CENTRE = 100

# THE RING, IN THE SAME WIREFRAME IDIOM AS THE BODY (2026-11-01, the owner's
# call). Three solid gold bands read as painted artwork sitting next to a
# wireframe globe — two different objects in one picture. Hairline concentric
# outlines read as the same object: a drawn ring, in a drawn system. The two
# edge radii run brighter, the way the A and B ring edges do, so the band
# still has a shape rather than dissolving into evenly spaced lines.
RING_RADII = [
    (52.0, "#e8c887", 0.9, 0.62),
    (47.0, "#c9a24b", 0.5, 0.32),
    (42.0, "#c9a24b", 0.5, 0.34),
    (37.0, "#8a6a2a", 0.5, 0.3),
    (33.0, "#e8c887", 0.9, 0.5),
]

# Latitude lines. The near half of each circle runs brighter than the far
# half, which is the cheapest honest depth cue in a wireframe.
LATITUDES = [0, 30, -30, 58, -58]


def ellipse_arc(rx, ry, cy, half):
    """Half of a horizontal ellipse centred at (0, cy), as an arc path.

    A sweep of 1 from the left end runs clockwise in SVG's y-down space, so it
    traces the upper half; starting from the right end traces the lower half.
    On this projection the lower half of any such ellipse lies nearer the
    camera, so "near" means lower and "far" means upper, for the ring and for
    every latitude line alike.
    """
    x = f"{rx:.2f}"
    if half == "far":
        return f"M -{x} {cy:.2f} A {x} {ry:.2f} 0 0 1 {x} {cy:.2f}"
    return f"M {x} {cy:.2f} A {x} {ry:.2f} 0 0 1 -{x} {cy:.2f}"


def ring_arcs(half):
    """One half of every ring radius. The far half runs at 40% of its own
    opacity, since it lies beyond the body and, for part of its sweep, inside
    the body's shadow."""
    out = []
    for r, colour, width, opacity in RING_RADII:
        shown = opacity if half == "near" else opacity * 0.4
        out.append(
            f'          <path d="{ellipse_arc(r, r * SIN_T, 0.0, half)}" fill="none" '
            f'stroke="{colour}" stroke-width="{width}" stroke-linecap="round" '
            f'opacity="{shown:.2f}"/>'
        )
    return LF.join(out)


def latitude_lines():
    out = []
    for lat in LATITUDES:
        rad = math.radians(lat)
        rx = R * math.cos(rad)
        ry = rx * SIN_T
        cy = -R * math.sin(rad) * COS_T
        width = 0.8 if lat == 0 else 0.7
        for half, opacity in (("far", 0.1), ("near", 0.26)):
            out.append(
                f'            <path d="{ellipse_arc(rx, ry, cy, half)}" fill="none" '
                f'stroke="#f2ead9" stroke-width="{width}" opacity="{opacity}"/>'
            )
    return "\n".join(out)


def planet():
    """A STILL Saturn, for a visitor whose JavaScript never runs.

    website/assets/globe.js removes this the moment it boots and draws the
    live globe in its place — twelve bodies, each wearing the same sphere,
    with Saturn's ring armature underneath every one of them. What stays
    here is the one frame that needs no script: the armature at rest, the
    body, the shading, the latitude lines and the pole.

    Its coordinates match the engine's exactly (TILT 26 degrees, R 30, a
    200-unit box), so the swap lands on the same geometry rather than
    jumping to it.
    """
    pole = R * COS_T
    turn = f"translate({CENTRE} {CENTRE}) rotate({ROLL})"
    return f"""      <svg class="planet" viewBox="0 0 200 200" aria-hidden="true" focusable="false">
        <defs>
          <radialGradient id="lockup-body" cx="34%" cy="28%" r="78%">
            <stop offset="0%" stop-color="#f7ecd4"/>
            <stop offset="45%" stop-color="#c9a24b"/>
            <stop offset="100%" stop-color="#4a3310"/>
          </radialGradient>
          <radialGradient id="lockup-shade" cx="74%" cy="80%" r="76%">
            <stop offset="0%" stop-color="#000000" stop-opacity="0.5"/>
            <stop offset="55%" stop-color="#000000" stop-opacity="0.16"/>
            <stop offset="100%" stop-color="#000000" stop-opacity="0"/>
          </radialGradient>
          <clipPath id="lockup-body-clip">
            <circle cx="0" cy="0" r="{R:.0f}"/>
          </clipPath>
        </defs>
        <g class="planet-still">
          <g class="ring ring-far" transform="{turn}">
{ring_arcs("far")}
          </g>

          <circle cx="{CENTRE}" cy="{CENTRE}" r="{R:.0f}" fill="url(#lockup-body)" opacity="0.55"/>

          <g transform="{turn}">
            <g clip-path="url(#lockup-body-clip)">
{latitude_lines()}
            </g>
            <circle cx="0" cy="{-pole:.2f}" r="1.1" fill="#f7ecd4" opacity="0.5"/>
          </g>

          <circle cx="{CENTRE}" cy="{CENTRE}" r="{R:.0f}" fill="url(#lockup-shade)" opacity="0.7"/>
          <circle cx="{CENTRE}" cy="{CENTRE}" r="{R - 0.4:.1f}" fill="none"
                  stroke="#f2ead9" stroke-width="0.8" opacity="0.45"/>

          <g class="ring ring-near" transform="{turn}">
{ring_arcs("near")}
          </g>
        </g>
      </svg>"""


# ── THE WORDMARK, IN FOUR LAYERS ──────────────────────────────────────────
# The letters were the one flat thing left in a masthead where everything
# else is drawn. A light now crosses behind them east to west and WRAPS:
# each word draws four times in register from the same glyphs — a heavy blur
# for the spill, a mid blur, a tight bright one for the edge catch, and the
# ivory wordmark untouched on top. The spill cannot help but take the shape
# of the letters, because it IS the letters, blurred.
#
# Nothing brightens the inside of a glyph. Light behind a letter rims its
# edges and spills around them; it does not illuminate its face.
#
# The three lit layers carry aria-hidden and the fourth does not, so a screen
# reader meets the word once. See site.css, "THE EFFULGENCE BEHIND THE
# WORDMARK", for why no layer carries mix-blend-mode.
def wordmark(text):
    layers = LF.join(
        f'      <span class="layer {cls}" aria-hidden="true">{text}</span>'
        for cls in ("halo", "mid", "rim")
    )
    return (f'    <span class="wordwrap">{LF}{layers}{LF}'
            f'      <span class="face">{text}</span>{LF}    </span>')


# ── THE INTERLUDE CRAFT ───────────────────────────────────────────────────
