CRAFT = {'disc': '<ellipse cx="35" cy="22" rx="26" ry="7" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><path d="M22 18 A 14 11 0 0 1 48 18" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><path d="M13 25 A 24 12 0 0 0 57 25" fill="none" stroke="#c9a24b" stroke-width="1.4"/><circle cx="24" cy="22" r="1.5" fill="#e8c887"/><circle cx="30" cy="23" r="1.5" fill="#e8c887"/><circle cx="36" cy="23.4" r="1.5" fill="#e8c887"/><circle cx="42" cy="23" r="1.5" fill="#e8c887"/><circle cx="48" cy="22" r="1.5" fill="#e8c887"/>', 'glocke': '<path d="M35 7 L35 12" stroke="#e8c887" stroke-width="1.3"/><circle cx="35" cy="6" r="2.2" fill="#e8c887"/><path d="M27 32 C 27 18, 29 13, 35 12 C 41 13, 43 18, 43 32 Z" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><ellipse cx="35" cy="33" rx="17" ry="4.5" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><path d="M21 21 Q 35 25 49 21" fill="none" stroke="#c9a24b" stroke-width="1"/><path d="M20 27 Q 35 31 50 27" fill="none" stroke="#c9a24b" stroke-width="1"/>', 'visitor': '<ellipse cx="35" cy="24" rx="26" ry="6.5" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><path d="M24 20 A 13 10 0 0 1 46 20" fill="#17140f" stroke="#f2ead9" stroke-width="1.4"/><ellipse cx="33" cy="15" rx="7" ry="6" fill="#6cc46a"/><path d="M40 14 L46 10" stroke="#6cc46a" stroke-width="1.4"/><circle cx="47" cy="9" r="2.4" fill="#6cc46a"/><path d="M30 15 L34 16" stroke="#17140f" stroke-width="1.2"/><path d="M14 27 A 23 11 0 0 0 56 27" fill="none" stroke="#c9a24b" stroke-width="1.3"/><circle cx="28" cy="24" r="1.5" fill="#e8c887"/><circle cx="35" cy="25" r="1.5" fill="#e8c887"/><circle cx="42" cy="24" r="1.5" fill="#e8c887"/>', 'noodle': '<circle cx="27" cy="16" r="7" fill="#b8402e"/><circle cx="44" cy="17" r="6.5" fill="#b8402e"/><path d="M33 10 L33 20 M39 10 L39 20" stroke="#f2ead9" stroke-width="1.3"/><circle cx="33" cy="8" r="2.6" fill="#f2ead9"/><circle cx="39" cy="8" r="2.6" fill="#f2ead9"/><path d="M8 23 Q 22 18 35 23 T 62 23" fill="none" stroke="#f2ead9" stroke-width="1.3"/><path d="M8 27 Q 22 22 35 27 T 62 27" fill="none" stroke="#e8dcc0" stroke-width="1.1"/><path d="M26 28 L22 36 M33 28 L31 37 M42 28 L46 36" stroke="#f2ead9" stroke-width="1"/>', 'apple': '<circle cx="35" cy="23" r="14" fill="#d8ab3f"/><path d="M35 9 Q 43 4 48 8 Q 43 13 36 11" fill="#6cc46a"/><path d="M31 7 L37 11 M37 7 L31 11" stroke="#f2ead9" stroke-width="1.2"/><path d="M28 12 A 14 14 0 0 0 28 34" fill="none" stroke="#9a7527" stroke-width="1"/><text x="35" y="26" font-size="5.5" font-family="Georgia,serif" fill="#5c4512" text-anchor="middle" letter-spacing=".3">KALLISTI</text>', 'lasagna': '<path d="M14 14 L58 11 L56 31 L12 34 Z" fill="#e8dcc0" stroke="#c9a24b" stroke-width="1"/><path d="M13 20 L57 17 M13 25 L57 22 M12.5 29 L56.5 26" stroke="#b8402e" stroke-width="2.6"/><path d="M50 5 L57 10 M64 5 L57 10" stroke="#f2ead9" stroke-width="1.2"/>'}

CRAFT_ORDER = ["disc", "glocke", "visitor", "noodle", "apple", "lasagna"]


def craft():
    out = []
    for n, name in enumerate(CRAFT_ORDER):
        style = (f"--at:{-n * 33}s;--lane:{-118 + n * 15}px;"
                 f"--exit:{-150 if n % 2 else -66}px;"
                 f"--spin:{-14 if n % 3 == 0 else 11}deg")
        out.append(f'  <svg class="craft" viewBox="0 0 70 40" aria-hidden="true" '
                   f'style="{style}">{CRAFT[name]}</svg>')
    return LF.join(out)


PLANET = planet()


# ─── THE NEBULA BEHIND THE BANNER ──────────────────────────────────────────
# Four blurred gas clouds drifting on long, offset cycles, so the masthead
# sits in deep space rather than on flat black. The technique comes from the
# owner's e-reader-screenshot-transcriber GUI (gui/public/style.css, the
# "Organic Drifting Nebula Gas Clouds" block): absolutely positioned discs,
# a heavy blur, mix-blend-mode screen, and a slow alternating float.
#
# RETINTED, NOT COPIED. That GUI runs quasar cyan, violet and magenta. This
# site runs ivory, gold and sun-flare orange on near-black, and a cyan cloud
# would read as a different brand. So gold and ember carry the effect here,
# with one deep violet behind them for distance and a trace of teal at the
# edge — see site.css, "THE MARQUEE NEBULA", for the per-cloud values.
#
# Markup rather than pseudo-elements because four clouds need four boxes, and
# it lands here so one script keeps all eleven pages in step.
# ─── THE STARFIELD THAT POPS IN ────────────────────────────────────────────
# The other half of the e-reader GUI's background, and the half the owner
# actually meant: stars that fade up out of nothing, peak, and fade back out,
# each on its own clock. Its @keyframes twinkle runs opacity 0 -> peak -> 0
# with a scale change, and animation-fill-mode: backwards holds a star
# invisible through its start delay so the page does not open on a flash of
# every star at once. Three shapes carry it: a round one with a glow, a
# five-point one cut with clip-path, and a crisp single pixel.
#
# WHY THE POSITIONS COME FROM A SEEDED GENERATOR. Fifty-four stars hand-placed
# would be fifty-four values to re-tune every time the count changes, and a
# runtime script would leave a no-JS visitor with a blank sky. random.Random
# with a fixed seed gives one field that every page shares and that regenerates
# identically — the page diff stays empty unless the seed or the count moves.
#
# The site already carries a .stars layer of static radial gradients, which
# stays: it dusts the whole viewport, and these pop on top of it.
STAR_SEED = 1101
STAR_COUNT = 54

# Ivory, bright gold, and one cool white, so the sky stays inside the palette.
STAR_TINTS = [
    ("rgba(242, 234, 217, 0.9)", 24),
    ("rgba(232, 200, 135, 0.9)", 14),
    ("rgba(214, 226, 240, 0.8)", 6),
]


# Visible dust, so the wind has something with body in it and not only
# pinpricks. Each mote goes into a drifting layer twice, like the stars, so
# the loop closes with no seam.
DUST = [
    ("rgba(232, 200, 135, 0.34)", 70, 12, 54),
    ("rgba(140, 110, 200, 0.3)", 24, 54, 78),
    ("rgba(255, 150, 80, 0.26)", 52, 74, 48),
    ("rgba(120, 190, 255, 0.26)", 84, 40, 66),
    ("rgba(242, 234, 217, 0.22)", 8, 66, 42),
    ("rgba(180, 120, 210, 0.26)", 38, 22, 60),
]


def mote(tint, left, top, size):
    return (f'<span class="mote" style="left:{left}%;top:{top}%;'
            f'width:{size}px;height:{size}px;'
            f'background:radial-gradient(circle,{tint},transparent 70%)"></span>')


def starfield():
    """The sky: most of it fixed, some of it on the wind.

    Three groups come out of one seeded pass. Two of them drift right to
    left — the near layer on 220s, the far on 440s — and each drifting layer
    holds its own field TWICE and travels exactly half its own width, so the
    loop closes with no seam. The rest stay put, and they are the majority
    on purpose: a sky where everything moves reads as a screensaver, and the
    fixed stars are what give the moving ones something to move against.

    The dust motes ride the same two layers, so the wind carries something
    with body in it and not only pinpricks.
    """
    rng = random.Random(STAR_SEED)
    tints = []
    for tint, count in STAR_TINTS:
        tints.extend([tint] * count)
    rng.shuffle(tints)

    far, near, fixed = [], [], []
    for n, (tint, left, top, size) in enumerate(DUST):
        (far if n % 2 else near).append(mote(tint, left, top, size))

    for i in range(STAR_COUNT):
        shape = "point" if i % 9 == 0 else ("pixel" if i % 4 == 0 else "round")
        size = rng.choice([1, 1, 1, 2, 2, 3]) if shape != "point" else rng.choice([3, 4, 5])
        style = (
            f"left:{rng.uniform(0, 100):.2f}%;"
            f"top:{rng.uniform(0, 100):.2f}%;"
            f"width:{size}px;height:{size}px;"
            f"--dur:{rng.uniform(3.2, 9.5):.1f}s;"
            f"--delay:{rng.uniform(0, 9):.1f}s;"
            f"--tint:{tints[i % len(tints)]};"
            f"--max-op:{rng.uniform(0.45, 0.95):.2f};"
            f"--glow:{size + 1}px"
        )
        star = f'<span class="star {shape}" style="{style}"></span>'
        # Roughly 45% of the sky travels; the rest holds station.
        if i % 4 == 0:
            near.append(star)
        elif i % 5 == 0:
            far.append(star)
        else:
            fixed.append(f"  {star}")

    def layer(cls, items):
        half = "".join(items)
        return (f'  <div class="drift {cls}"><div>{half}</div>'
                f'<div>{half}</div></div>')

    out = ['<div class="starfield" aria-hidden="true">']
    out.append(layer("drift-near", near))
    out.append(layer("drift-far", far))
    out.extend(fixed)
    out.append("</div>")
    return LF.join(out)


NEBULA = """<div class="nebula" aria-hidden="true">
  <span class="neb neb-gold"></span>
  <span class="neb neb-ember"></span>
  <span class="neb neb-violet"></span>
  <span class="neb neb-teal"></span>
</div>"""


def url(filename):
    """The link Cloudflare Pages actually serves.

    Pages strips .html and answers the extension with a 308, so every
    href="videos.html" cost the visitor a redirect before the page began —
    128 of them across eleven pages (finding 10). The NAV table above keeps
    filenames, because they match the files on disk and the page argument;
    only the emitted href changes.

    python -m http.server cannot serve these, so local preview runs through
    serve.py, which mirrors the rewriting.
    """
    if filename == "index.html":
        return "/"
    return filename[: -len(".html")] if filename.endswith(".html") else filename


def masthead(page):
    home = ' aria-current="page"' if page == "index.html" else ""
    links = []
    for href, label, flip in NAV:
        current = ' aria-current="page"' if href == page else ""
        text = f'<span class="flip">{label}</span>' if flip else label
        links.append(f'    <a href="{url(href)}"{current}>{text}</a>')
    return "\n".join([
        BEGIN,
        '<header class="masthead">',
        # The weather belongs TO the banner, not to the page. Both of these
        # used to sit outside the header as fixed, viewport-wide layers,
        # which put the gas and the dense star cluster behind the whole
        # site. They hang inside it now and the header's overflow clips
        # them. The page keeps its own sparse .stars sprinkle, which lives
        # in the page template rather than here.
        NEBULA,
        starfield(),
        f'  <a class="lockup" href="/" aria-label="Da’at Data, home"{home}>',
        # The light rides INSIDE the lockup, so its centre is the wordmark's
        # centre rather than the header box's — the nav row below would
        # otherwise pull the flex centre down and light the gap.
        '    <span class="rays" aria-hidden="true"><i></i></span>',
        '    <span class="glow" aria-hidden="true"></span>',
        wordmark('Da’at'),
        PLANET,
        wordmark('Data'),
        '  </a>',
        '  <nav class="sitenav" aria-label="Sections">',
        *links,
        '  </nav>',
        craft(),
        '</header>',
        # The globe's turn needs trigonometry per frame, so the lockup carries
        # one script. defer, and in the body, so it never blocks the paint.
        '<script src="assets/globe.js" defer></script>',
        rail(),
        END,
    ])


OLD_NAV = re.compile(r'<nav class="sitenav">.*?</nav>', re.S)
MARKED = re.compile(re.escape(BEGIN) + r".*?" + re.escape(END), re.S)


def main():
    pages = sorted(PAGES.glob("*.html"))
    if not pages:
        sys.exit("no pages found")
    for path in pages:
        html = path.read_text(encoding="utf-8")
        block = masthead(path.name)
        if MARKED.search(html):
            out = MARKED.sub(lambda _: block, html, count=1)
        elif OLD_NAV.search(html):
            out = OLD_NAV.sub(lambda _: block, html, count=1)
        else:
            print(f"  skipped {path.name}: no masthead marker and no old nav")
            continue
        if out != html:
            path.write_text(out, encoding="utf-8")
            print(f"  wrote {path.name}")
        else:
            print(f"  unchanged {path.name}")


if __name__ == "__main__":
    main()
